namespace Motherson;
public static class ConsultaModelo {
 public record Familia(string Tabla,string Identidad,string Select,string Filtro);
 static readonly Dictionary<string,Familia> Familias=new(){["catalog"] = new("l1.CONFIGURACION_POSICION","id_posicion","SELECT CONVERT(bigint,x.id_version) WireRevision,p.codigo_posicion_origen WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],p.codigo_posicion_origen AS [key],CONVERT(bigint,x.[piezas_por_caja]) AS [factor],x.[capacidad_cajas] AS [capacity_boxes],CONVERT(bigint,x.[capacidad_piezas]) AS [capacity],CONVERT(bigint,x.[minimo_piezas]) AS [minimum],CONVERT(bigint,x.[inventario_inicial]) AS [initial],x.[estado] AS [status],x.[datos_documentales_json] AS [data],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_alta_utc]) AS [created_t],x.[naturaleza_posicion] AS [Naturaleza],m.numero_parte part,es.codigo_estacion station,e.codigo_estanteria rack,u.nivel level,pl.codigo_puesto post FROM l1.CONFIGURACION_POSICION x JOIN l1.POSICION p ON p.id_posicion=x.id_posicion JOIN l1.MATERIAL m ON m.id_material=p.id_material JOIN l1.UBICACION u ON u.id_ubicacion=p.id_ubicacion JOIN l1.ESTANTERIA e ON e.id_estanteria=u.id_estanteria JOIN l1.ESTACION es ON es.id_estacion=e.id_estacion JOIN l1.PUESTO_LOGISTICO pl ON pl.id_puesto=p.id_puesto WHERE 1=1","p.codigo_posicion_origen=@identidad"),
["events"] = new("l1.REGISTRO","id_registro","SELECT CONVERT(bigint,x.id_version) WireRevision,CONVERT(nvarchar(80),x.id_registro) WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],CONVERT(bigint,x.[id_registro]) AS [id],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_evento_utc]) AS [t],CONVERT(bigint,x.[saldo_anterior]) AS [before],CONVERT(bigint,x.[saldo_posterior]) AS [after],CONVERT(bigint,x.[cantidad_movimiento]) AS [delta],CONVERT(bigint,x.[cantidad_demandada]) AS [demand],CONVERT(bigint,x.[cantidad_faltante]) AS [missing],CONVERT(bigint,x.[cantidad_cajas]) AS [boxes],CONVERT(bigint,x.[id_solicitud]) AS [order_id],x.[fecha_evento_local] AS [local],x.[tipo_registro] AS [kind],x.[escenario] AS [scenario],(SELECT codigo_turno FROM l1.TURNO WHERE id_turno=x.[id_turno]) AS [shift],x.[proceso_generador] AS [actor],x.[rol_responsable] AS [responsibility_role],x.[naturaleza_responsable] AS [responsibility_nature],x.[origen] AS [origin],x.[motor] AS [engine],x.[estado_alarma] AS [alarm_state],x.[politica_alarma] AS [alarm_policy],x.[estado_alarma_anterior] AS [previous_alarm_state],p.codigo_posicion_origen AS [key],x.[id_usuario] AS [user_id],x.[id_asignacion] AS [assignment_id],x.[numero_paso_consumo] AS [consumption_ordinal],x.[semilla] AS [seed],x.[id_usuario_autorizador] AS [authorization_user_id],x.[id_autorizacion_turno] AS [turn_access_id],x.[id_autorizador_asignacion] AS [assignment_authorizer],x.[id_transaccion] AS [transaction_id],x.[id_ejecucion_consumo] AS [consumption_run],x.[fecha_registro_utc] AS [recorded_utc],x.[fecha_programada_utc] AS [planned_utc],x.[fecha_fin_asignacion_utc] AS [assignment_until],x.[huella_configuracion] AS [config_hash],x.[es_cobertura] AS [is_cover],CONVERT(bigint,x.[id_registro_desencadenante]) AS [trigger_event_id],CONVERT(bigint,x.[piezas_consumidas_referencia]) AS [referenceConsumed],x.[cobertura_minutos] AS [coverageMinutes],x.[tasa_piezas_minuto] AS [ratePiecesMinute],x.[minutos_referencia] AS [referenceMinutes],x.[inicio_referencia] AS [referenceStart],x.[fin_referencia] AS [referenceEnd],x.[motivo_evaluacion] AS [evaluation_reason],x.[cantidad_muestras] AS [samples],x.[huella_atribucion] AS [ActorId],x.[severidad] AS [severity],x.[color] AS [color],x.[prioridad] AS [priority],x.[politica] AS [policy],x.[explicacion] AS [explanation] FROM l1.REGISTRO x LEFT JOIN l1.POSICION p ON p.id_posicion=x.id_posicion WHERE 1=1","x.id_registro=TRY_CONVERT(int,@identidad)"),
["orders"] = new("l1.ESTADO_SOLICITUD","id_solicitud","SELECT CONVERT(bigint,x.id_version) WireRevision,CONVERT(nvarchar(80),x.id_solicitud) WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],CONVERT(bigint,x.[id_solicitud]) AS [id],p.codigo_posicion_origen AS [key],x.[escenario] AS [scenario],CONVERT(bigint,x.[piezas_reservadas]) AS [reserved_pieces],x.[cantidad_cajas] AS [boxes],(SELECT codigo_puesto FROM l1.PUESTO_LOGISTICO WHERE id_puesto=x.[id_puesto]) AS [post],(SELECT codigo_turno FROM l1.TURNO WHERE id_turno=x.[id_turno_inicio]) AS [start_shift],x.[minutos_trabajados] AS [working_minutes],x.[proceso_generador] AS [generator],x.[prioridad] AS [priority],x.[motivo_prioridad] AS [priority_reason],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_prioridad_utc]) AS [priority_at],x.[politica_prioridad] AS [priority_policy],x.[cobertura_prioridad_minutos] AS [priority_coverage],x.[campos_responsables_origen] AS [ResponsablesCampos] FROM l1.ESTADO_SOLICITUD x JOIN l1.POSICION p ON p.id_posicion=x.id_posicion WHERE 1=1","x.id_solicitud=TRY_CONVERT(int,@identidad)"),
["stops"] = new("l1.PARO","id_paro","SELECT CONVERT(bigint,x.id_version) WireRevision,CONVERT(nvarchar(80),x.id_paro) WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],CONVERT(bigint,x.[id_paro]) AS [id],p.codigo_posicion_origen AS [key],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_inicio_utc]) AS [start],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_fin_utc]) AS [end],CONVERT(bigint,x.[id_solicitud]) AS [order_id],x.[escenario] AS [scenario],x.[causa] AS [cause],x.[es_manual] AS [manual] FROM l1.PARO x JOIN l1.POSICION p ON p.id_posicion=x.id_posicion WHERE 1=1","x.id_paro=TRY_CONVERT(int,@identidad)"),
["cuts"] = new("l1.CIERRE_TURNO","id_cierre","SELECT CONVERT(bigint,x.id_version) WireRevision,CONVERT(nvarchar(80),x.id_cierre) WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],CONVERT(bigint,x.[id_cierre]) AS [id],DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),x.[fecha_cierre_utc]) AS [t],x.[fecha_cierre_local] AS [local],(SELECT codigo_turno FROM l1.TURNO WHERE id_turno=x.[id_turno]) AS [shift],p.codigo_posicion_origen AS [key],CONVERT(bigint,x.[saldo_piezas]) AS [stock],CONVERT(bigint,x.[minimo_piezas]) AS [minimum],x.[pasa_siguiente_turno] AS [passed],CONVERT(bigint,x.[id_solicitud_pendiente]) AS [pending_order],CONVERT(bigint,x.[piezas_reservadas]) AS [reserved],x.[tiene_paro_abierto] AS [stop_open],x.[id_usuario] AS [user_id],x.[nombre_responsable] AS [responsible_name],x.[fecha_registro_utc] AS [recorded_utc] FROM l1.CIERRE_TURNO x JOIN l1.POSICION p ON p.id_posicion=x.id_posicion WHERE 1=1","x.id_cierre=TRY_CONVERT(int,@identidad)"),
["people"] = new("l1.RESPONSABLE_SIMULADO","codigo_responsable","SELECT CONVERT(bigint,x.id_version) WireRevision,x.codigo_responsable WireKey,x.es_base WireBase,x.campos_origen WireFields,CONVERT(bigint,x.[id_version]) AS [RevisionId],x.[codigo_responsable] AS [id],x.[nombre_responsable] AS [name],(SELECT codigo_puesto FROM l1.PUESTO_LOGISTICO WHERE id_puesto=x.[id_puesto]) AS [post],(SELECT codigo_turno FROM l1.TURNO WHERE id_turno=x.[id_turno]) AS [shift],x.[datos_origen_json] AS [data] FROM l1.RESPONSABLE_SIMULADO x WHERE 1=1","x.codigo_responsable=@identidad")};
 public static string Leer(string tabla,bool? baseOnly,long? despues,long? hasta,bool actual,string? identidad){var f=Familias[tabla];return f.Select+(baseOnly.HasValue?" AND x.es_base=@base":"")+(despues.HasValue?" AND x.id_version>@after":"")+(hasta.HasValue?" AND x.id_version<=@through":"")+(identidad is not null?" AND "+f.Filtro:"")+(actual?" AND NOT EXISTS(SELECT 1 FROM "+f.Tabla+" n WHERE n."+f.Identidad+"=x."+f.Identidad+" AND n.id_version>x.id_version)":"")+" ORDER BY x.es_base DESC,WireKey,x.id_version";}
 public static string Actuaciones(bool? baseOnly,long? despues,long? hasta,bool actual,string? identidad)=>"SELECT CONVERT(bigint,a.id_version_solicitud),a.codigo_etapa,DATEDIFF_BIG(microsecond,CONVERT(datetime2(6),'19700101'),a.fecha_actuacion_utc),a.huella_atribucion,a.tiene_atribucion FROM l1.ACTUACION_SOLICITUD a JOIN l1.ESTADO_SOLICITUD x ON x.id_version=a.id_version_solicitud WHERE 1=1"+(baseOnly.HasValue?" AND x.es_base=@base":"")+(despues.HasValue?" AND x.id_version>@after":"")+(hasta.HasValue?" AND x.id_version<=@through":"")+(identidad is not null?" AND x.id_solicitud=TRY_CONVERT(int,@identidad)":"")+(actual?" AND NOT EXISTS(SELECT 1 FROM l1.ESTADO_SOLICITUD n WHERE n.id_solicitud=x.id_solicitud AND n.id_version>x.id_version)":"");
}
